// Chi xu ly message tu DEVICE, bo qua ASSET va cac loai khac
if (msgType === 'POST_TELEMETRY_REQUEST' || msgType === 'POST_ATTRIBUTES_REQUEST') {
    if (metadata.deviceType !== undefined && metadata.deviceType !== null) {
        return ['device'];
    }
}
return ['other'];

// Enrich message voi device info
var newMetadata = metadata;
newMetadata.originatorDeviceId = metadata.deviceName;
newMetadata.originatorDeviceType = metadata.deviceType;
return {msg: msg, metadata: newMetadata, msgType: msgType};

// Kiem tra co automation rules khong
var automations = metadata.homeAutomations;
return automations !== null && automations !== undefined && automations !== '' && automations !== '[]';

// ====== SMARTHOME AUTOMATION ENGINE - CONDITION EVALUATOR ======
// Node nay doc automation rules tu Home Asset attribute,
// evaluate conditions dua tren telemetry hien tai,
// va tra ve danh sach actions can thuc hien.

var automations = JSON.parse(metadata.homeAutomations || '[]');
var triggeredActions = [];
var now = new Date();
var currentHour = now.getHours();
var currentMinute = now.getMinutes();
var currentDay = now.getDay(); // 0=Sun, 1=Mon...6=Sat
// Convert to 1=Mon...7=Sun format
var dayOfWeek = currentDay === 0 ? 7 : currentDay;
var currentTimeMinutes = currentHour * 60 + currentMinute;

for (var i = 0; i < automations.length; i++) {
    var rule = automations[i];

    // Skip disabled rules
    if (!rule.enabled) continue;

    // Skip rules that target gateway execution
    if (rule.execution_target && rule.execution_target.startsWith('gateway:')) continue;

    // Check effective period
    if (rule.extra && rule.extra.effective_period) {
        var ep = rule.extra.effective_period;
        if (ep.type === 'custom') {
            // Check days
            if (ep.days && ep.days.indexOf(dayOfWeek) === -1) continue;
            // Check time range
            if (ep.from && ep.to) {
                var epFrom = parseInt(ep.from.split(':')[0]) * 60 + parseInt(ep.from.split(':')[1]);
                var epTo = parseInt(ep.to.split(':')[0]) * 60 + parseInt(ep.to.split(':')[1]);
                if (currentTimeMinutes < epFrom || currentTimeMinutes > epTo) continue;
            }
        }
    }

    var conditionsMet = [];
    var hasDeviceConditionForOrigin = false;

    for (var j = 0; j < rule.conditions.length; j++) {
        var cond = rule.conditions[j];
        var met = false;

        switch (cond.type) {
            case 'device_state':
                // Chi evaluate neu message den tu device nay
                if (cond.device_id === metadata.originatorId) {
                    hasDeviceConditionForOrigin = true;
                    var val = msg[cond.attribute];
                    if (val !== undefined && val !== null) {
                        switch (cond.operator) {
                            case '>':  met = val > cond.value; break;
                            case '<':  met = val < cond.value; break;
                            case '>=': met = val >= cond.value; break;
                            case '<=': met = val <= cond.value; break;
                            case '==': met = val == cond.value; break;
                            case '!=': met = val != cond.value; break;
                        }
                    }
                } else {
                    // Device khac - can query rieng (simplified: skip)
                    met = false;
                }
                break;

            case 'time_range':
                var fromParts = cond.from.split(':');
                var toParts = cond.to.split(':');
                var fromMin = parseInt(fromParts[0]) * 60 + parseInt(fromParts[1]);
                var toMin = parseInt(toParts[0]) * 60 + parseInt(toParts[1]);
                if (fromMin <= toMin) {
                    met = currentTimeMinutes >= fromMin && currentTimeMinutes <= toMin;
                } else {
                    // Overnight: e.g., 22:00 - 06:00
                    met = currentTimeMinutes >= fromMin || currentTimeMinutes <= toMin;
                }
                break;

            case 'time_schedule':
                // Simplified cron check - chi ho tro format "M H * * *"
                if (cond.cron) {
                    var cronParts = cond.cron.split(' ');
                    if (cronParts.length >= 2) {
                        var cronMin = cronParts[0] === '*' ? currentMinute : parseInt(cronParts[0]);
                        var cronHour = cronParts[1] === '*' ? currentHour : parseInt(cronParts[1]);
                        met = (currentHour === cronHour && currentMinute === cronMin);
                    }
                }
                break;

            case 'day_of_week':
                met = cond.days && cond.days.indexOf(dayOfWeek) !== -1;
                break;

            case 'device_offline':
                // Check qua metadata.isOnline (neu co)
                if (cond.device_id === metadata.originatorId) {
                    met = metadata.isOnline === 'false';
                }
                break;
        }

        conditionsMet.push(met);
    }

    // Rule phai co it nhat 1 device condition lien quan den device hien tai
    if (!hasDeviceConditionForOrigin && rule.conditions.some(function(c) { return c.type === 'device_state'; })) {
        continue;
    }

    // Evaluate match type
    var allMet = false;
    if (rule.condition_match === 'any') {
        allMet = conditionsMet.some(function(v) { return v === true; });
    } else {
        // Default: 'all'
        allMet = conditionsMet.length > 0 && conditionsMet.every(function(v) { return v === true; });
    }

    if (allMet) {
        triggeredActions.push({
            ruleId: rule.id,
            ruleName: rule.name,
            actions: rule.actions
        });
    }
}

if (triggeredActions.length > 0) {
    var newMsg = {
        triggeredRules: triggeredActions,
        triggerDevice: metadata.originatorDeviceId || metadata.deviceName,
        triggerDeviceId: metadata.originatorId,
        timestamp: now.getTime()
    };
    return {msg: newMsg, metadata: metadata, msgType: 'AUTOMATION_TRIGGERED'};
} else {
    return {msg: msg, metadata: metadata, msgType: 'NO_MATCH'};
}

// Tach triggered rules thanh tung action rieng le
// Moi action se duoc xu ly rieng
var allActions = [];
for (var i = 0; i < msg.triggeredRules.length; i++) {
    var rule = msg.triggeredRules[i];
    for (var j = 0; j < rule.actions.length; j++) {
        var action = rule.actions[j];
        action._ruleId = rule.ruleId;
        action._ruleName = rule.ruleName;
        action._actionIndex = j;
        allActions.push(action);
    }
}

// Tra ve action dau tien, cac action con lai luu vao metadata
var newMetadata = metadata;
newMetadata.pendingActions = JSON.stringify(allActions);
newMetadata.triggerDevice = msg.triggerDevice;
newMetadata.triggerTimestamp = msg.timestamp;

if (allActions.length > 0) {
    return {msg: allActions[0], metadata: newMetadata, msgType: 'EXECUTE_ACTION'};
}
return {msg: msg, metadata: metadata, msgType: msgType};

// Route action theo type
switch (msg.type) {
    case 'device_command': return ['device_command'];
    case 'delay':          return ['delay'];
    case 'send_notification': return ['notification'];
    case 'run_scene':      return ['run_scene'];
    default:               return ['unknown'];
}

// Chuyen doi action thanh RPC request format
var rpcRequest = {
    method: msg.command,
    params: msg.params || {}
};

// Luu target device ID vao metadata
var newMetadata = metadata;
newMetadata.targetDeviceId = msg.device_id;
newMetadata.rpcMethod = msg.command;
newMetadata.actionRuleId = msg._ruleId;
newMetadata.actionRuleName = msg._ruleName;

// Neu device thuoc gateway, them gateway_id
if (msg.gateway_id) {
    newMetadata.targetGatewayId = msg.gateway_id;
}

return {msg: rpcRequest, metadata: newMetadata, msgType: 'RPC_CALL_FROM_SERVER_TO_DEVICE'};

// Tao notification message
var notification = {
    title: 'SmartHome Automation',
    body: msg.message || ('Automation "' + metadata.actionRuleName + '" triggered'),
    target: msg.target || 'owner',
    ruleId: msg._ruleId,
    ruleName: msg._ruleName,
    timestamp: new Date().getTime()
};
return {msg: notification, metadata: metadata, msgType: 'SEND_NOTIFICATION'};

configuration.alarmDetailsBuildJs:
var details = {};
details.message = msg.body;
details.ruleName = msg.ruleName;
details.ruleId = msg.ruleId;
return details;

